// auth.ts implementation
class EcommerceAuthHandler {
  async authenticateCheckout(session: Session, order: Order) {
    if (order.total > this.config.security.highValueThreshold) {
      return await this.requireStepUpAuth(session);
    }
    return await this.validateStandardAuth(session);
  }

  async requireStepUpAuth(session: Session) {
    // Temporary elevated authentication for high-value transactions
    const stepUpToken = await this.generateStepUpChallenge();
    await this.sendMFAChallenge(session.user.email, stepUpToken);
    return { requiresStepUp: true, challengeToken: stepUpToken };
  }
}
```

